for(const kind of kinds)for(const point of ['initial submit lock','normalization','control list','input freeze'])test(`${kind}: pre-provider ${point} fault is known-unwritten, not an unknown save`,async()=>{
 const h=setup();prepare(h,kind);const raw=h.bytes(),counts=count(h),form=h.dom.ids.get('modal-form'),query=form.querySelectorAll;let fired=0;
 if(point==='initial submit lock')trap(h,'modal-submit','disabled',value=>{if(value&&!fired++){throw Error('Injected entry lock failure');}});
 else if(point==='input freeze'){const input={get disabled(){return false;},set disabled(value){if(value&&!fired++){throw Error('Injected freeze failure');}}};form.querySelectorAll=selector=>selector==='input,select,textarea,button'?[input]:query(selector);}
 else form.querySelectorAll=selector=>{if(selector===(point==='normalization'?'[data-round]':'input,select,textarea,button')&&!fired++){throw Error('Injected '+point+' failure');}return query(selector);};
 await h.submit();assert.ok(fired);assert.equal(h.bytes(),raw);assert.equal(h.counters.attempts,0);same(count(h),counts);assert.equal(ui(h).submitDisabled,false);assert.equal(h.store.reloadRequired??false,false);assert.match(ui(h).modalError,/Injected/);assert.doesNotMatch(ui(h).modalError,/outcome.*could not be confirmed|saved, but/);form.querySelectorAll=query;await h.submit();assert.equal(h.counters.writes,1);assert.equal(ui(h).modalOpen,false);
});
test('contract-offer failure paths swallow no safety guard and produce no unhandled rejection when role/reporting throws',async()=>{const unhandled=[],listener=error=>unhandled.push(error);process.on('unhandledRejection',listener);try{for(const kind of kinds)for(const committed of [false,true]){const h=setup();prepare(h,kind);const gate=serviceSaveGate(h.store),operation=h.submit();if(committed)gate.entries[0].write();h.hooks.onRole=()=>{throw Error('Injected terminal role failure');};trap(h,'message','textContent',value=>{if(/Reload/.test(value))throw Error('Injected terminal reporter failure');});gate.entries[0].reject();await operation;assert.equal(h.store.reloadRequired,true);assert.equal(h.store.editable,false);assert.equal(h.counters.writes,Number(committed));gate.restore();}await flush();assert.deepEqual(unhandled,[]);}finally{process.off('unhandledRejection',listener);}});
